-- Permanent balances, historical orders and ledger rows remain unchanged.
ALTER TABLE orders ADD COLUMN purchase_type TEXT NOT NULL DEFAULT 'credits' CHECK(purchase_type IN ('credits','subscription'));
CREATE TABLE stripe_customers(user_id TEXT NOT NULL REFERENCES users(id),provider_mode TEXT NOT NULL CHECK(provider_mode IN ('test','live')),customer_id TEXT NOT NULL,PRIMARY KEY(user_id,provider_mode),UNIQUE(provider_mode,customer_id));
CREATE TABLE subscriptions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),provider_mode TEXT NOT NULL CHECK(provider_mode IN ('test','live')),plan_id TEXT NOT NULL,billing_interval TEXT NOT NULL CHECK(billing_interval IN ('month','year')),price_id TEXT NOT NULL,amount_cents INTEGER NOT NULL CHECK(amount_cents>0),monthly_credits INTEGER NOT NULL CHECK(monthly_credits>0),customer_id TEXT,subscription_id TEXT,checkout_id TEXT,checkout_url TEXT,checkout_return_path TEXT,status TEXT NOT NULL DEFAULT 'pending',sync_version INTEGER NOT NULL DEFAULT 0,cancel_at_period_end INTEGER NOT NULL DEFAULT 0 CHECK(cancel_at_period_end IN(0,1)),current_period_start INTEGER,current_period_end INTEGER,checkout_expires_at INTEGER,created_at INTEGER NOT NULL DEFAULT(unixepoch()),updated_at INTEGER NOT NULL DEFAULT(unixepoch()),UNIQUE(provider_mode,subscription_id),UNIQUE(provider_mode,checkout_id));
CREATE UNIQUE INDEX subscriptions_one_open ON subscriptions(user_id,provider_mode) WHERE status IN ('pending','incomplete','active','trialing','past_due','unpaid','paused');
CREATE TABLE subscription_invoices(id TEXT PRIMARY KEY,subscription_id TEXT NOT NULL REFERENCES subscriptions(id),user_id TEXT NOT NULL REFERENCES users(id),provider_mode TEXT NOT NULL CHECK(provider_mode IN('test','live')),invoice_id TEXT NOT NULL,period_start INTEGER NOT NULL,period_end INTEGER NOT NULL CHECK(period_end>period_start),billing_interval TEXT NOT NULL CHECK(billing_interval IN('month','year')),monthly_credits INTEGER NOT NULL CHECK(monthly_credits>0),created_at INTEGER NOT NULL DEFAULT(unixepoch()),UNIQUE(provider_mode,invoice_id),UNIQUE(subscription_id,period_start));
CREATE TABLE subscription_credit_periods(id TEXT PRIMARY KEY,invoice_id TEXT NOT NULL REFERENCES subscription_invoices(id),subscription_id TEXT NOT NULL REFERENCES subscriptions(id),user_id TEXT NOT NULL REFERENCES users(id),starts_at INTEGER NOT NULL,ends_at INTEGER NOT NULL CHECK(ends_at>starts_at),granted INTEGER NOT NULL CHECK(granted>0),remaining INTEGER NOT NULL CHECK(remaining>=0 AND remaining<=granted),UNIQUE(subscription_id,starts_at));
CREATE INDEX subscription_credit_available ON subscription_credit_periods(user_id,starts_at,ends_at);
CREATE TABLE generation_credit_allocations(generation_id TEXT PRIMARY KEY REFERENCES generations(id),permanent_amount INTEGER NOT NULL CHECK(permanent_amount>=0));
CREATE TABLE generation_subscription_allocations(generation_id TEXT NOT NULL REFERENCES generation_credit_allocations(generation_id),period_id TEXT NOT NULL REFERENCES subscription_credit_periods(id),amount INTEGER NOT NULL CHECK(amount>0),PRIMARY KEY(generation_id,period_id));
DROP TRIGGER generation_charge;
DROP TRIGGER ledger_balance;
DROP TRIGGER ledger_apply;
-- A generation insert and every debit below form one SQLite transaction. Stable
-- ordering by expiry/start/id also permits multiple overlapping paid buckets.
CREATE TRIGGER generation_charge AFTER INSERT ON generations BEGIN  SELECT CASE WHEN NEW.cost>(SELECT credits FROM users WHERE id=NEW.user_id)+COALESCE((SELECT SUM(remaining) FROM subscription_credit_periods WHERE user_id=NEW.user_id AND starts_at<=unixepoch() AND ends_at>unixepoch()),0) THEN RAISE(ABORT,'insufficient_credits') END;  INSERT INTO generation_credit_allocations(generation_id,permanent_amount) VALUES(NEW.id,MAX(0,NEW.cost-COALESCE((SELECT SUM(remaining) FROM subscription_credit_periods WHERE user_id=NEW.user_id AND starts_at<=unixepoch() AND ends_at>unixepoch()),0)));  INSERT INTO generation_subscription_allocations(generation_id,period_id,amount) SELECT NEW.id,p.id,MIN(p.remaining,MAX(0,NEW.cost-COALESCE((SELECT SUM(q.remaining) FROM subscription_credit_periods q WHERE q.user_id=NEW.user_id AND q.starts_at<=unixepoch() AND q.ends_at>unixepoch() AND (q.ends_at,q.starts_at,q.id)<(p.ends_at,p.starts_at,p.id)),0))) FROM subscription_credit_periods p WHERE p.user_id=NEW.user_id AND p.starts_at<=unixepoch() AND p.ends_at>unixepoch() AND p.remaining>0 AND NEW.cost>COALESCE((SELECT SUM(q.remaining) FROM subscription_credit_periods q WHERE q.user_id=NEW.user_id AND q.starts_at<=unixepoch() AND q.ends_at>unixepoch() AND (q.ends_at,q.starts_at,q.id)<(p.ends_at,p.starts_at,p.id)),0);  UPDATE subscription_credit_periods SET remaining=remaining-(SELECT amount FROM generation_subscription_allocations WHERE generation_id=NEW.id AND period_id=subscription_credit_periods.id) WHERE id IN(SELECT period_id FROM generation_subscription_allocations WHERE generation_id=NEW.id);  INSERT INTO credit_ledger(id,user_id,amount,kind,reference_id) VALUES(NEW.id||':debit',NEW.user_id,-NEW.cost,'generation',NEW.id); END;
CREATE TRIGGER ledger_balance BEFORE INSERT ON credit_ledger WHEN NOT EXISTS(SELECT 1 FROM credit_ledger WHERE kind=NEW.kind AND reference_id=NEW.reference_id) BEGIN  SELECT CASE WHEN (SELECT credits FROM users WHERE id=NEW.user_id)+(CASE WHEN NEW.kind='subscription_grant' THEN 0 WHEN NEW.kind='generation' AND EXISTS(SELECT 1 FROM generation_credit_allocations WHERE generation_id=NEW.reference_id) THEN -(SELECT permanent_amount FROM generation_credit_allocations WHERE generation_id=NEW.reference_id) ELSE NEW.amount END)<0 THEN RAISE(ABORT,'insufficient_credits') END; END;
CREATE TRIGGER ledger_apply AFTER INSERT ON credit_ledger BEGIN  UPDATE users SET credits=credits+(CASE WHEN NEW.kind='subscription_grant' THEN 0 WHEN NEW.kind IN('generation','refund') AND EXISTS(SELECT 1 FROM generation_credit_allocations WHERE generation_id=NEW.reference_id) THEN (CASE WHEN NEW.kind='generation' THEN -1 ELSE 1 END)*(SELECT permanent_amount FROM generation_credit_allocations WHERE generation_id=NEW.reference_id) ELSE NEW.amount END) WHERE id=NEW.user_id;  UPDATE subscription_credit_periods SET remaining=remaining+(SELECT amount FROM generation_subscription_allocations WHERE generation_id=NEW.reference_id AND period_id=subscription_credit_periods.id) WHERE NEW.kind='refund' AND id IN(SELECT period_id FROM generation_subscription_allocations WHERE generation_id=NEW.reference_id); END;
